    """Recolor alternating 4-connected color-2 objects, counting from right."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0]) if grid else 0
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            components.append(cells)

    # Alternate by horizontal order, beginning with the rightmost object.
    components.sort(key=lambda cells: (min(c for _, c in cells), min(r for r, _ in cells)))
    for i, cells in enumerate(reversed(components)):
        if i % 2 == 0:
            for r, c in cells:
                out[r][c] = 8
    return out
